import{releasedPool as f}from"../pool-version.js";import{hash as c,shuffle as p}from"../../daily/puzzles.js";import{wordBoards as u}from"./word-board-data.js";export function wordBoard(n){const l=f("wordboards",u,n.split(":")[0]),i=l[c(n)%l.length],t=Array(25).fill("#");for(let o=0;o<3;o++)for(let r=0;r<5;r++)t[o*10+r]=i[o][r];for(let o=0;o<3;o++)for(let r=0;r<5;r++)t[r*5+o*2]=i[o+3][r];return{words:i,solution:t}}export function makeWordGrid(n){const{words:l,solution:i}=wordBoard(n),t=[...i],o=p(i.flatMap((s,e)=>s!=="#"?[e]:[]),n+":tiles");let r=0;while(o.length>1&&r<8){const s=o.shift(),e=o.findIndex((a)=>t[s]!==t[a]);if(e<0)break;const d=o.splice(e,1)[0];[t[s],t[d]]=[t[d],t[s]];r++}return{kind:"wordgrid",size:5,words:l,solution:i,initial:t,maxMoves:15}}